/// <reference types="@figma/plugin-typings" />

// Component visual defaults sourced from coui_core (the SSOT). Generated by
// `dart run packages/coui_core/bin/export_figma_components.dart` (schema
// v2 — see `packages/coui_core/bin/figma_reader/schema_v2.dart`) and
// inlined into code.js at build time (esbuild json loader). Builders read
// colors / radius / padding / border from here instead of hardcoding token
// names, so a change in coui_core propagates to Figma on the next export +
// build.
//
// ─── Why there are no hand-written per-component interfaces here ──────────
//
// This file used to declare one interface per component (`ButtonData`,
// `CardData`, …) hand-curated against schema v1's shape. Schema v2 changed
// that shape entirely — every component is now `{fields, variants, sizes}`
// (`schema_v2.dart`'s "every component has the same shape" contract) — and
// the v1 interfaces went stale silently: `tsc` never caught it, because the
// old code cast the import with `as unknown as ComponentsDoc`, which
// discards structural checking against the JSON's actual shape.
//
// `tsconfig.json` sets `resolveJsonModule: true`, so a plain
// `import componentsJson from './data/components.json'` already gives
// every component's *exact* literal field set — no interface to fall out
// of sync with the generator's actual output, and no cast that could hide
// a mismatch. This file's only job is exposing that inferred structure
// under short names, plus the two leaf-shape adapters
// (`compat/v1.ts#colorData`/`textStyleData`) that convert schema v2's
// `Color`/`TextLeaf` leaves into the shapes `helpers.ts`'s paint functions
// already know how to consume — `Dim` leaves need no adapter, since every
// dimensional helper in `helpers.ts` already accepts `number | Dim`
// (#3753).
//
// A dispatch table (`variants.defaultsByVariant`, `sizes.defaultsBySize`,
// …) is best consumed with `Object.entries(...)`, not
// `Object.keys(...)` + bracket indexing — TS rejects indexing a
// JSON-inferred object type with a plain `string` (no index signature),
// but `for (const [name, v] of Object.entries(...))` gives `v` the
// precise union of every entry's literal type, so fields every entry
// shares (e.g. button's `background`/`foreground`) type-check directly.
// A field only *some* entries carry (e.g. button's `outline`-only
// `borderColor`) needs `optField<T>(v, 'borderColor')`
// (`compat/v1.ts`) instead of `v.borderColor`.

import type { ComponentAxesJson } from './axis-combos';
import componentsJson from './data/components.json';

// ─── Single typed accessor ──────────────────────────────────────────────────
//
// `resolveJsonModule` infers this from the committed JSON's actual
// content — no cast, no hand-written document interface.
const DOC = componentsJson;

export const COMPONENTS = DOC.components;

// The type scale's per-role metrics, emitted at the document root because a
// role belongs to the scale rather than to whichever component references it
// (one row per role, against hundreds of references). Exported so the fidelity
// readback can resolve a role name to the size it should have rendered at — the check that
// would have caught all 218 rendering at a hardcoded 14.
export const TYPOGRAPHY = DOC.typography;

/** The dials of the GLASS effect a refracting surface wears, in the plugin API's
 *  units (`surfaceGlassJson` in `export_figma_components.dart`). */
export interface SurfaceGlassJson {
  /** The style these dials are read from — for the log, not for a lookup. */
  style: string;
  refraction: number;
  depth: number;
  dispersion: number;
  lightAngle: number;
  lightIntensity: number;
}

// Root-level, beside `typography`, because the dials belong to a surface STYLE
// and not to any component. Null when no style refracts — the export writes
// null rather than omitting the key, and the widening below is what lets a
// build against such an export typecheck.
export const SURFACE_GLASS: SurfaceGlassJson | null =
  (DOC as { surfaceGlass?: SurfaceGlassJson | null }).surfaceGlass ?? null;

// REGISTRY name (`TextField`) → components.json key (`text_field`). Lives
// here, next to the JSON it indexes, because every caller that needs it
// needs it for the same reason — `generate.ts`'s placement/hash/docs
// lookups, the docs frames, the G10 ratchet. Three copies of one regex is
// three chances for one of them to drift out of agreement with the export.
export function slugOfName(name: string): string {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();
}

// #4023 (B2) — schema v3 `section` accessor for page placement. Dynamic
// (slug-string) indexing over the literal-typed JSON needs one structural
// widening; the fold itself lives in coui_core's section_reader (single
// source), this just reads the folded result.
const componentsBySlug: Record<
  string,
  {
    section: { name: string | null; sourceCategory: string | null };
    docs: { order: number | null };
  }
> = COMPONENTS;

// Whether the reader produced an entry for this slug at all.
//
// Distinct from "has no section": no entry means there is nothing to compare a
// canvas node against, so that component's values are unverifiable rather than
// merely unsorted.
export function hasEntry(slug: string): boolean {
  return componentsBySlug[slug] !== undefined;
}

export function sectionNameOf(slug: string): string | null {
  const entry = componentsBySlug[slug];
  return entry ? entry.section.name : null;
}

// This component's position in `kDocsComponentEntries` — the flat, curated
// (not alphabetical) order docs_site's sidebar and overview grid render in
// (`docs_core/lib/shared/component_catalog.dart`, read by
// `packages/coui_core/bin/figma_reader/docs_reader.dart`'s catalog walk and
// exported as `docs.order`).
//
// `null` for a component the catalog doesn't list — an infra/internal one, or
// one that genuinely predates a catalog entry — and that has to be
// distinguished from "documented at position 0": a page-ordering comparator
// that treated both as `0` would interleave undocumented pages into the
// curated block instead of placing them after it.
export function docsOrderOf(slug: string): number | null {
  const entry = componentsBySlug[slug];
  return entry ? entry.docs.order : null;
}

// Pure comparator: docs_site's curated order first, alphabetical only for
// what the catalog doesn't rank. Extracted from `generate.ts`'s page-sort
// call site so it is testable without a `PageNode`, a `Map`, or a live
// document — a plain function of two optional ints and two names.
//
// A page whose `order` is non-null always sorts before one whose is null:
// collapsing "documented at position 0" and "undocumented" to the same
// sentinel would interleave infra/internal pages into the middle of a
// curated block instead of trailing them.
export function compareByDocsOrder(
  orderA: number | null,
  orderB: number | null,
  nameA: string,
  nameB: string,
): number {
  if (orderA !== null && orderB !== null) return orderA - orderB;
  if (orderA !== null) return -1;
  if (orderB !== null) return 1;
  return nameA < nameB ? -1 : nameA > nameB ? 1 : 0;
}

// #4100 (D-27) — page naming, the single source generate (placement) and
// verify (conformance) both read; a second derivation is how the two could
// silently disagree. The scheme mirrors the reference library the user
// pointed at: an emoji + UPPERCASE section header page precedes each
// section block, and component pages carry a `❖ ` glyph with no section
// segment (the header pages carry the section, so repeating it 100+ times
// in the sidebar is noise).
//
// One entry per section the v3 fold can produce (`section_reader.dart`'s
// `kSectionFold`), which is one entry per docs catalog group — the two
// lists are the same list, so a section added there needs a glyph here or
// its header page falls back to a bare uppercase name.
const kSectionHeaderEmoji: Record<string, string> = {
  Control: '🎛️',
  Form: '📝',
  Display: '🖥️',
  Layout: '📐',
  Navigation: '🧭',
  Menu: '🗂️',
  Overlay: '💬',
  Icon: '⭐',
  Text: '🔤',
  Infra: '🧱',
};

/** `Badge` → `❖ Badge`. Every registry component gets a page. */
//
// The page name is the component's name; the v3 section is not part of it (D-27 —
// the header pages carry the section, so repeating it 100+ times in the sidebar is
// noise). So a component with no section still has a page name, and this used to
// return null for one, on the reasoning that a missing section meant the JSON and
// the REGISTRY had drifted.
//
// That reasoning held while every registry entry had a section. It stopped holding
// when the registry grew past what the docs describe: a handful of components have
// no description in either docs source, and six have no directory of their own for
// the fold to read. Thirteen entries were in that state and every one of them was
// SKIPPED — the components did not reach the canvas at all, over a section that
// only orders pages.
//
// Ordering handles the absence by itself: `sectionIndexOf` puts an unsectioned page
// after the known blocks. What a missing section deserves is a line in the log,
// not a component held off the page.
/** 생성기가 소유하는 페이지의 접두. 컴포넌트 이름을 모르는 채 "이 페이지는
 *  빌더가 그리는 페이지인가" 를 물어야 하는 자리가 쓴다 — 고아 노드 검출
 *  (`orphan-nodes.ts`)이 그 자리다. `componentPageNameOf` 가 이 상수로 이름을
 *  만들므로 둘이 갈릴 수 없고, `selftest-orphan-nodes` 가 그 포함 관계를
 *  단언한다. */
export const kComponentPageNamePrefix = '❖ ';

export function componentPageNameOf(componentName: string): string {
  return `${kComponentPageNamePrefix}${componentName}`;
}

/** 디자이너가 **강등한** 페이지인가 — `❖` 를 빼고 이름 앞을 들여써 섹션 아래
 *  메모로 내린 페이지(`  Stacks`). 생성기는 이것을 옵트아웃으로 읽어 그 항목을
 *  빌드하지 않고(`↷ skipped — its page is demoted`), verify 의 배치 판정도 같은
 *  규칙으로 읽는다.
 *
 *  한 함수인 이유: 두 곳이 규칙을 각자 적으면 갈린다. 실제로 갈렸다 — #4026
 *  실측(09-24)에서 생성기가 일부러 건너뛴 19개를 배치 판정이 "페이지 없음" 으로
 *  신고했다. 재실행으로 지울 수 없는 빨강이다.
 *
 *  들여쓰기가 조건이다: 들여쓰지 않은 `Stacks` 는 강등이 아니라 이름이 같은
 *  아무 페이지이고, 생성기는 그 옆에 `❖ Stacks` 를 만든다. */
export function isDemotedPageOf(pageName: string, entryName: string): boolean {
  return /^\s+/.test(pageName) && pageName.trim() === entryName;
}

/// A page name with any leading `NN. ` / `N-N. ` ordering prefix removed.
///
/// The canvas numbers its section headers (`01. 🎛️ CONTROL`) while
/// [sectionHeaderPageNameOf] returns the bare form (`🎛️ CONTROL`). The
/// number is the designer's sidebar ordering and is theirs to keep — this
/// exists so it cannot HIDE the page from a name lookup.
///
/// Same prefix shape as the one `withoutOrderingPrefix` in `variables.ts`
/// strips from a collection name.
export function withoutPageOrderPrefix(name: string): string {
  return name.trim().replace(/^\d+(?:-\d+)*\.\s*/, '');
}

/// Which existing page a target page name should reuse, or `null` to create
/// a new one.
///
/// Split out of `generate.ts`'s `ensurePage` so it can be tested without a
/// Figma environment — `ensurePage` itself only maps this answer back to a
/// `PageNode`, and nothing else in the plugin's self-tests reaches it.
///
/// THE BUG THIS EXISTS FOR. The lookup was `targetPages.get(pageName)`, an
/// exact-name match. Every section header on the canvas carries an ordering
/// prefix the generated name does not, so all ten missed and `ensurePage`
/// minted a second, empty header for each — on EVERY run, whatever the
/// scope, because placement normalization is not scoped. Measured: a run
/// that built one component took the file from 188 pages to 198. Nothing
/// failed; the duplicates simply accumulated.
///
/// Exact match wins over a prefix-tolerant one so a file that already uses
/// the bare names is unaffected.
export function pageToReuse(
  existingNames: readonly string[],
  target: string,
): string | null {
  if (existingNames.includes(target)) return target;
  const bare = withoutPageOrderPrefix(target);
  for (const name of existingNames) {
    if (withoutPageOrderPrefix(name) === bare) return name;
  }
  return null;
}

/** `Display` → `🖥️ DISPLAY` — the section-block header page's name. */
export function sectionHeaderPageNameOf(section: string): string {
  const emoji = kSectionHeaderEmoji[section];
  return emoji ? `${emoji} ${section.toUpperCase()}` : section.toUpperCase();
}

/**
 * The order the plugin's own pages should read in: a header per non-empty
 * section, then that section's component pages.
 *
 * Headers are the bare names (`📝 FORM`); the file may number them
 * (`02. 📝 FORM`) — [resolvePlannedPages] reads both as the same page.
 * [sectionPages] is already in the order each block should read; this only
 * decides what surrounds it. Whether a run may MOVE pages to match is not
 * this function's question — [pageOrderMoves] answers it per scope, and a run
 * that leaves existing pages alone still needs the plan to place the pages it
 * created.
 */
export function plannedPageOrder(
  sectionOrder: readonly string[],
  sectionPages: ReadonlyMap<string, readonly string[]>,
): string[] {
  const planned: string[] = [];
  for (const section of sectionOrder) {
    const pages = sectionPages.get(section) ?? [];
    // A section with no component page in this file gets no header — a
    // scoped run on a fresh file should not plant ten headers for nine
    // sections it never built.
    if (pages.length === 0) continue;
    planned.push(sectionHeaderPageNameOf(section), ...pages);
  }
  return planned;
}

/** A page as the ordering decision sees it — the id is what tells apart the
 *  many pages that share a name (`---`, `--`). */
export interface PageRef {
  readonly id: string;
  readonly name: string;
}

/** `all` — put every page the plugin owns in plan order. `created` — leave
 *  every existing page where it is and place only the pages this run made. */
export type PageOrderScope = 'all' | 'created';

export interface PageMove {
  readonly id: string;
  /** A page already at its final position when this move is applied. */
  readonly anchorId: string;
  readonly side: 'before' | 'after';
  readonly reason: 'header' | 'new' | 'order';
}

export interface PageOrderDecision {
  /** Apply in array order — each anchor is final by the time it is used. */
  readonly moves: readonly PageMove[];
  /** The page ids in the order the moves produce, for an after-the-fact check. */
  readonly order: readonly string[];
  /** Plugin-owned pages left where they were. */
  readonly kept: number;
  /** Plan entries no page answers to (a header a scoped run did not create). */
  readonly unresolved: readonly string[];
}

/** Does this page mark a block edge in the sidebar — a divider, or a numbered
 *  title like `999. Screen`? A plugin-owned page is never kept on the far side
 *  of one from the rest of its section, so a component page that ended up
 *  under someone else's title is moved back rather than left there because it
 *  happens to be in sequence. */
export function isSidebarBoundaryPage(name: string): boolean {
  // Figma draws an empty page whose name is only dashes, asterisks or spaces
  // as a divider; this file's dividers are hyphens.
  if (name.length > 0 && /^[\s\-–—*]+$/.test(name)) return true;
  return withoutPageOrderPrefix(name) !== name.trim();
}

/**
 * Which page each plan entry is, as a page id or `null`.
 *
 * Headers follow [pageToReuse] — exact name first, then a page whose name
 * matches once an ordering prefix is removed — because the canvas numbers
 * them and the plan does not. When two pages answer to one header, the oldest
 * page (lowest id) is the header: picking by document order would pick the
 * other one as soon as a run moved the first, and two runs would trade them
 * back and forth forever.
 *
 * A component page is its exact name. Every page with that name is in the plan
 * (the plan is built from the file's pages), so each plan entry simply takes
 * the first one not already taken.
 */
export function resolvePlannedPages(
  pages: readonly PageRef[],
  plan: readonly string[],
): (string | null)[] {
  const taken = new Set<string>();
  const take = (match: (p: PageRef) => boolean, oldestFirst: boolean): string | null => {
    const candidates = pages.filter((p) => !taken.has(p.id) && match(p));
    if (candidates.length === 0) return null;
    const found = oldestFirst ? [...candidates].sort((a, b) => comparePageIds(a.id, b.id))[0] : candidates[0];
    taken.add(found.id);
    return found.id;
  };
  return plan.map((name) => {
    if (name.startsWith(kComponentPageNamePrefix)) return take((p) => p.name === name, false);
    const bare = withoutPageOrderPrefix(name);
    return (
      take((p) => p.name === name, true) ??
      take((p) => withoutPageOrderPrefix(p.name) === bare, true)
    );
  });
}

/** Figma ids are `session:counter`; an earlier session or counter is an older
 *  node. Anything else compares as a string — the order only has to be stable. */
function comparePageIds(a: string, b: string): number {
  const pa = /^(\d+):(\d+)$/.exec(a);
  const pb = /^(\d+):(\d+)$/.exec(b);
  if (pa && pb) return Number(pa[1]) - Number(pb[1]) || Number(pa[2]) - Number(pb[2]);
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * The page moves that put the plugin's own pages — component pages and
 * section headers — in plan order, keeping the longest stretch already in
 * order where it is and never moving anyone else's page. Other pages keep
 * their order among themselves; one that sat between a header and its first
 * page ends up above the header, because the header moves down onto its page.
 *
 * Pure: the ordering pass in `generate.ts` turns the moves into
 * `insertChild` calls and nothing else, so everything this decides is tested
 * on name lists in `selftest-page-order`.
 *
 * WHY IT IS SHAPED LIKE THIS. The pass it replaces looked a page up by exact
 * name and treated a miss as "not there yet, insert it after the previous
 * plan entry". Numbered headers always missed, so each one was moved behind
 * the previous section's last page on every run — and when that page had
 * been created at the end of the file, the header went to the end too. The
 * same lookup never placed a component page at all, because by the time it
 * ran the build pass had already created the page at the end. The rules
 * below each answer one of those:
 *
 * - **Keep the longest chain already in order.** A file someone arranged
 *   reads mostly right; moving only what breaks the order keeps their
 *   dividers, notes and previews next to what they were placed beside. On a
 *   file already in order the chain is everything and there are no moves —
 *   which is what makes a re-run a no-op.
 * - **A header is in place only directly above its first page.** A header
 *   that is merely in sequence can sit above the previous block's notes and
 *   divider and still look ordered; anchoring it to its own first page is
 *   what keeps "divider → header → pages" intact. "First page" skips pages
 *   this run created — those are at the end of the file and say nothing
 *   about where the header is.
 * - **No divider or numbered title inside a kept stretch of one section.**
 *   Otherwise a page left under `999. Screen` stays there for being in
 *   sequence.
 * - **A page this run created is not kept** under `all`, wherever it landed,
 *   so it goes to its section — unless every plugin page is new (a fresh
 *   file), when something has to be the anchor. Under `created` the run's
 *   own pages are the only thing that moves.
 *
 * Placement fills each gap between kept neighbours L and R: the part of the
 * gap that belongs to L's section goes right after L, and from the gap's
 * first header on, everything goes right before R — so the header lands on
 * its first page and the notes/divider between L and R stay between the two
 * blocks.
 */
export function pageOrderMoves(
  pages: readonly PageRef[],
  plan: readonly string[],
  options: { readonly scope: PageOrderScope; readonly created: ReadonlySet<string> },
): PageOrderDecision {
  const { scope, created } = options;
  const resolved = resolvePlannedPages(pages, plan);
  const posOf = new Map(pages.map((p, i) => [p.id, i]));

  interface Item {
    readonly id: string;
    readonly pos: number;
    readonly section: number;
    readonly header: boolean;
  }
  const items: Item[] = [];
  const unresolved: string[] = [];
  let section = -1;
  plan.forEach((name, k) => {
    const header = !name.startsWith(kComponentPageNamePrefix);
    if (header) section++;
    const id = resolved[k];
    if (id == null) {
      unresolved.push(name);
      return;
    }
    items.push({ id, pos: posOf.get(id) ?? -1, section, header });
  });

  // Boundary pages that are not ours, as a prefix count so "is there one
  // between positions a and b" is a subtraction.
  const owned = new Set(items.map((it) => it.id));
  const boundariesBefore: number[] = [0];
  for (const p of pages) {
    const isBoundary = !owned.has(p.id) && isSidebarBoundaryPage(p.name);
    boundariesBefore.push(boundariesBefore[boundariesBefore.length - 1] + (isBoundary ? 1 : 0));
  }
  const boundaryBetween = (a: number, b: number): boolean =>
    boundariesBefore[b] - boundariesBefore[a + 1] > 0;

  let kept: boolean[];
  if (scope === 'created') {
    kept = items.map((it) => !created.has(it.id));
  } else {
    const glued = (i: number): boolean => {
      const it = items[i];
      if (!it.header) return true;
      // The page that tells where this header belongs is the first page of its
      // section that the run did not just create. A page created this run sits
      // at the end of the file and says nothing about the header — judging the
      // header by it would drag a header that is already in place across the
      // notes and divider under it.
      const first = items.slice(i + 1).find((x) => x.section === it.section && !created.has(x.id));
      if (first === undefined) return true;
      return pages[it.pos + 1]?.id === first.id;
    };
    const longestChain = (eligible: (i: number) => boolean): boolean[] => {
      const n = items.length;
      const length = new Array<number>(n).fill(0);
      const previous = new Array<number>(n).fill(-1);
      let best = -1;
      for (let j = 0; j < n; j++) {
        if (!eligible(j)) continue;
        length[j] = 1;
        for (let i = 0; i < j; i++) {
          if (length[i] === 0 || items[i].pos >= items[j].pos) continue;
          const sameSection = items[i].section === items[j].section;
          if (sameSection && boundaryBetween(items[i].pos, items[j].pos)) continue;
          // Strictly longer only — the first chain found wins a tie, so the
          // decision does not depend on anything but its inputs.
          if (length[i] + 1 > length[j]) {
            length[j] = length[i] + 1;
            previous[j] = i;
          }
        }
        if (best === -1 || length[j] > length[best]) best = j;
      }
      const keep = new Array<boolean>(n).fill(false);
      for (let at = best; at !== -1; at = previous[at]) keep[at] = true;
      return keep;
    };
    kept = longestChain((i) => !created.has(items[i].id) && glued(i));
    // A fresh file: every page was created by this run. Something has to be
    // the anchor, so let the run's own pages qualify — the header rule stays.
    if (!kept.some(Boolean)) kept = longestChain(glued);
    // Nothing qualifies at all (no component page): the first entry anchors.
    if (!kept.some(Boolean) && items.length > 0) kept[0] = true;
  }

  const order = pages.map((p) => p.id);
  const moves: PageMove[] = [];
  const place = (item: Item, anchorId: string, side: 'before' | 'after'): void => {
    const from = order.indexOf(item.id);
    const anchorAt = order.indexOf(anchorId);
    if (side === 'after' ? order[anchorAt + 1] === item.id : order[anchorAt - 1] === item.id) return;
    order.splice(from, 1);
    order.splice(order.indexOf(anchorId) + (side === 'after' ? 1 : 0), 0, item.id);
    moves.push({
      id: item.id,
      anchorId,
      side,
      reason: item.header ? 'header' : created.has(item.id) ? 'new' : 'order',
    });
  };
  let k = 0;
  while (k < items.length) {
    if (kept[k]) {
      k++;
      continue;
    }
    let j = k;
    while (j + 1 < items.length && !kept[j + 1]) j++;
    const left = k > 0 ? items[k - 1] : null;
    const right = j + 1 < items.length ? items[j + 1] : null;
    const gap = items.slice(k, j + 1);
    const firstHeader = gap.findIndex((it) => it.header);
    const tail = firstHeader === -1 ? gap : gap.slice(0, firstHeader);
    const head = firstHeader === -1 ? [] : gap.slice(firstHeader);
    let last = left;
    for (const it of tail) {
      if (last) place(it, last.id, 'after');
      else if (right) place(it, right.id, 'before');
      last = it;
    }
    head.forEach((it, i) => {
      if (i === 0 && right) place(it, right.id, 'before');
      else if (last) place(it, last.id, 'after');
      last = it;
    });
    k = j + 1;
  }

  return { moves, order, kept: kept.filter(Boolean).length, unresolved };
}

// #4041 (D3) — schema v3 `docs` accessor for the inspector surfaces
// (ComponentNode.description / documentationLinks). Same structural
// widening as `sectionNameOf`; the description priority (한국어 md →
// 영어 카탈로그 → null) was already resolved at export time.
const docsBySlug: Record<
  string,
  { docs: { description: string | null; url: string; lang: string | null } }
> = COMPONENTS;

export function docsOf(slug: string): { description: string | null; url: string } {
  const entry = docsBySlug[slug];
  return entry
    ? { description: entry.docs.description, url: entry.docs.url }
    : { description: null, url: '' };
}

// #4039 (D1) / #4040 (D2) — the three subtrees the documentation frames
// project. Same structural widening as `sectionNameOf`/`docsOf`, for the
// same reason (dynamic slug indexing over literal-typed JSON), and kept as
// three narrow accessors rather than one `COMPONENTS[slug]` escape hatch so
// a caller cannot quietly widen its own reach past what it declared.
//
// `axes` reuses `ComponentAxesJson` from axis-combos.ts instead of
// restating the shape — a second declaration of the same JSON subtree is
// exactly the drift `data.ts`'s own header warns about.

const axesBySlug: Record<string, { axes: ComponentAxesJson }> = COMPONENTS;

export function axesOf(slug: string): ComponentAxesJson | null {
  const entry = axesBySlug[slug];
  return entry ? entry.axes : null;
}

const examplesBySlug: Record<
  string,
  { examples: { withStyle: string | null; tokenChain: string | null } }
> = COMPONENTS;

export function examplesOf(slug: string): {
  withStyle: string | null;
  tokenChain: string | null;
} {
  const entry = examplesBySlug[slug];
  return entry ? entry.examples : { withStyle: null, tokenChain: null };
}

// The v2 chrome subtree — nested by field name, leaves are `{v, ref, via}`
// (dimensional) or `{argb, ref, opacity, fallbacks}` (color). Left as
// `unknown` values on purpose: the docs table walks the tree generically
// and narrows each leaf where it reads it, so a new leaf shape shows up as
// a summary this file never had to be taught about.
const fieldsBySlug: Record<string, { fields: Record<string, unknown> }> = COMPONENTS;

export function fieldsOf(slug: string): Record<string, unknown> {
  const entry = fieldsBySlug[slug];
  return entry ? entry.fields : {};
}

// #3740 (A-1b) — the canonical Figma library record, build-time-inlined from
// docs_core/content/_data/figma_library.json via export_figma_components.dart.
// `identifier` is what generate.ts compares against the open document's root
// pluginData stamp (warn-only, never blocks — see checkCanonicalLibrary in
// generate.ts for why).
export interface CanonicalLibraryMeta {
  identifier: string | null;
  displayName: string | null;
  url: string | null;
}

export const CANONICAL_LIBRARY: CanonicalLibraryMeta = DOC.meta.canonicalLibrary;

// ─── Per-component accessors ────────────────────────────────────────────────
//
// One line per component, added as its builder converts (#3754/#3755) —
// `COMPONENTS.<slug>` is always available directly for anything not yet
// named here.

export const BUTTON = COMPONENTS.button;
export const TEXT_FIELD = COMPONENTS.text_field;
export const CHECKBOX = COMPONENTS.checkbox;
export const TOGGLE = COMPONENTS.toggle;
export const RADIO_GROUP = COMPONENTS.radio_group;
export const CARD = COMPONENTS.card;
export const BADGE = COMPONENTS.badge;
export const ALERT = COMPONENTS.alert;
export const STATUS = COMPONENTS.status;
export const STAT = COMPONENTS.stat;
